#!/usr/bin/env python3
"""TASK-20260929-739a0c -- supplement: dependence of the Q6 envelopes on the extra grid point
log2 B_cap(4), read from path1_q6_table.csv (this task's own output). Prints JSON."""
import csv
import json

rows = list(csv.DictReader(open('path1_q6_table.csv')))
X_CAP = [float(r['log2_B']) for r in rows if r['point'] == 'log2_Bcap4'][0]
out = {}
for rname in ('range_a', 'range_b'):
    for with_extra in (True, False):
        key = '%s_%s' % (rname, 'with_extra' if with_extra else 'without_extra')
        res = {}
        for g in ['0', '6', '10', '13', '14', '20', '25', '30', '31', '31.5', '32']:
            sel = [r for r in rows if r['g'] == g and (with_extra or r['point'] != 'log2_Bcap4')
                   and (rname == 'range_b' or float(r['log2_B']) <= X_CAP + 1e-12)]
            ne = [r for r in sel if r['log2_L_lo'] != 'empty']
            if not ne:
                res[g] = 'empty (%d points)' % len(sel)
                continue
            lo = min(ne, key=lambda r: float(r['log2_L_lo']))
            hi = max(ne, key=lambda r: float(r['log2_L_hi']))
            res[g] = dict(n_points=len(sel), n_nonempty=len(ne), lo=lo['log2_L_lo'], lo_at=lo['point'],
                          hi=hi['log2_L_hi'], hi_at=hi['point'])
        out[key] = res
# differences
diff = {}
for rname in ('range_a', 'range_b'):
    d = {}
    for g, v in out[rname + '_with_extra'].items():
        w = out[rname + '_without_extra'][g]
        if isinstance(v, str) or isinstance(w, str):
            d[g] = 'with=%s | without=%s' % (v if isinstance(v, str) else 'nonempty', w if isinstance(w, str) else 'nonempty')
        else:
            d[g] = dict(lo_shift_bits=round(float(w['lo']) - float(v['lo']), 10),
                        hi_shift_bits=round(float(w['hi']) - float(v['hi']), 10))
    diff[rname] = d
out['shift_when_extra_point_removed'] = diff
print(json.dumps(out, indent=1))

